-- Travel > Stays, first batch (Sean, 2026-11-11: "I want us to start filling up the travel directory... Hotels"; source he sent:
-- myvegantravels.com/travel-tips/vegan-hotels, updated 2026-09-16). Fifteen 100% Vegan stays and three the source calls Vegan-friendly (filed as plant-based (Pre-Vegan) options).
-- Staged ON HOLD (status pending): the session could not reach the hotels' own sites to check each one, as the cruises were checked.
-- Each goes live (status approved) once it is checked on its own site. Website is the hotel's own site, never the source's affiliate link.
-- Safe to run twice: skips a slug that already exists.
insert into listings (name, slug, category, status, website, vegan_status, tagline, specialty, description, location, address_city, address_state, address_country,
  crawl_source, tenant_id, business_status, details)
select n, s, 'Stays', 'pending', w, vs, t, t, d, loc, nullif(city, ''), nullif(st, ''), cc, 'admin', '00000000-0000-4000-a000-000000000002', 'OPERATIONAL',
